refrigerate_the_salmon:
def policy():
    walk("kitchen")
    find("salmon")
    salmon = parse_objects("visible salmon")
    if not salmon or not acquire_object(salmon[0]):
        return
    find("fridge")
    fridges = parse_objects("visible fridges")
    if fridges and place_held_in_container(salmon[0], fridges[0]):
        close(fridges[0])

