put_apple_in_fridge:
def policy():
    walk("kitchen")
    apples = [o for o in get_visible_objects() if o.name == "apple"]
    for apple in apples:
        if walk(apple).status == "succeeded" and grab(apple).status == "succeeded":
            find("fridge")
            open("fridge")
            putin(apple, "fridge")
            close("fridge")
            break
